create table public.hotel_import_batches(
  id uuid primary key default gen_random_uuid(),
  property_id uuid not null references public.properties(id) on delete cascade,
  entity_type text not null default 'reservations' check(entity_type in('reservations')),
  source_system text,
  file_name text,
  mapping jsonb not null default '{}'::jsonb,
  status text not null default 'draft' check(status in('draft','validated','ready','importing','completed','failed','cancelled')),
  stats jsonb not null default '{}'::jsonb,
  created_by uuid,
  validated_at timestamptz,
  imported_at timestamptz,
  imported_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.hotel_import_rows(
  id bigint generated by default as identity primary key,
  batch_id uuid not null references public.hotel_import_batches(id) on delete cascade,
  property_id uuid not null references public.properties(id) on delete cascade,
  row_number integer not null,
  raw_data jsonb not null default '{}'::jsonb,
  normalized_data jsonb not null default '{}'::jsonb,
  validation jsonb not null default '{}'::jsonb,
  row_hash text,
  import_status text not null default 'staged' check(import_status in('staged','valid','invalid','duplicate','skipped','imported','failed')),
  imported_reservation_id bigint references public.reservas(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(batch_id,row_number)
);

create index hotel_import_batches_property_created_idx on public.hotel_import_batches(property_id,created_at desc);
create index hotel_import_rows_batch_status_idx on public.hotel_import_rows(batch_id,import_status,row_number);
create index hotel_import_rows_property_hash_idx on public.hotel_import_rows(property_id,row_hash) where row_hash is not null;

alter table public.hotel_import_batches enable row level security;
alter table public.hotel_import_rows enable row level security;
create policy hotel_import_batches_select_access on public.hotel_import_batches for select to authenticated using(private.user_has_property_access(property_id));
create policy hotel_import_batches_insert_management on public.hotel_import_batches for insert to authenticated with check(private.user_has_property_role(property_id,array['owner','manager','admin']) and (created_by is null or created_by=(select auth.uid())));
create policy hotel_import_rows_select_access on public.hotel_import_rows for select to authenticated using(private.user_has_property_access(property_id));
create policy hotel_import_rows_insert_management on public.hotel_import_rows for insert to authenticated with check(private.user_has_property_role(property_id,array['owner','manager','admin']) and exists(select 1 from public.hotel_import_batches b where b.id=batch_id and b.property_id=property_id));

revoke all on table public.hotel_import_batches from anon,authenticated;
revoke all on table public.hotel_import_rows from anon,authenticated;
grant select,insert on table public.hotel_import_batches to authenticated;
grant select,insert on table public.hotel_import_rows to authenticated;
grant usage,select on sequence public.hotel_import_rows_id_seq to authenticated;

create or replace function public.hl_emit_reservation_automation_events()
returns trigger language plpgsql security definer set search_path to 'public','pg_temp'
as $function$
declare v_trigger text;a record;v_message text;
begin
  if current_setting('app.hl_import_mode',true)='on' then return new; end if;
  if tg_op='INSERT' then v_trigger:='reservation_created';
  elsif new.estado is distinct from old.estado and new.estado='alojado' then v_trigger:='checkin';
  elsif new.estado is distinct from old.estado and new.estado='finalizada' then v_trigger:='checkout';
  else return new; end if;
  for a in select id,name,action_code from public.hotel_automations where property_id=new.property_id and enabled=true and trigger_code=v_trigger loop
    v_message:=case v_trigger when 'reservation_created' then coalesce(a.name,'Automatización')||': nueva reserva de '||coalesce(new.nombre_huesped,'Huésped') when 'checkin' then coalesce(a.name,'Automatización')||': check-in de '||coalesce(new.nombre_huesped,'Huésped') when 'checkout' then coalesce(a.name,'Automatización')||': check-out de '||coalesce(new.nombre_huesped,'Huésped') else coalesce(a.name,'Automatización') end;
    insert into public.hotel_automation_events(property_id,automation_id,event_type,message,reservation_id,room_id,dedupe_key) values(new.property_id,a.id,v_trigger,v_message,new.id,new.habitacion_id,v_trigger||':'||new.id::text||':'||coalesce(new.estado,'')) on conflict do nothing;
    update public.hotel_automations set runs=coalesce(runs,0)+1,last_run_at=now(),updated_at=now() where id=a.id;
  end loop;return new;
end;$function$;

create or replace function public.hl_channel_reservation_queue_trigger()
returns trigger language plpgsql security definer set search_path to 'public','pg_temp'
as $function$
declare pid uuid:=coalesce(new.property_id,old.property_id);df date:=least(coalesce(new.fecha_entrada,old.fecha_entrada),coalesce(old.fecha_entrada,new.fecha_entrada));dt date:=greatest(coalesce(new.fecha_salida,old.fecha_salida),coalesce(old.fecha_salida,new.fecha_salida));
begin if current_setting('app.hl_import_mode',true)='on' then return coalesce(new,old);end if;perform public.hl_channel_queue_change(pid,'inventory','reservation_change',df,dt);return coalesce(new,old);end;$function$;

create or replace function public.hl_import_validate_batch(p_batch_id uuid)
returns jsonb language plpgsql security definer set search_path to 'public','private','pg_temp'
as $function$
declare
 v_batch public.hotel_import_batches%rowtype;r public.hotel_import_rows%rowtype;v_norm jsonb;v_errors jsonb;v_warnings jsonb;v_action text;v_guest text;v_external text;v_source_key text;v_room_id bigint;v_room_capacity integer;v_checkin date;v_checkout date;v_pax integer;v_total numeric;v_paid numeric;v_currency text;v_hash text;v_duplicate_id bigint;c_total integer:=0;c_valid integer:=0;c_invalid integer:=0;c_duplicate integer:=0;c_skipped integer:=0;c_warning integer:=0;
begin
 select * into v_batch from public.hotel_import_batches where id=p_batch_id;if not found then raise exception using errcode='P0002',message='Lote de importación no encontrado.';end if;
 if not private.user_has_property_role(v_batch.property_id,array['owner','manager','admin']) then raise exception using errcode='42501',message='No tenés permisos para validar esta importación.';end if;
 select count(*) into c_total from public.hotel_import_rows where batch_id=p_batch_id and property_id=v_batch.property_id;if c_total=0 then raise exception using errcode='22023',message='El lote no tiene filas.';end if;if c_total>2500 then raise exception using errcode='54000',message='El lote supera 2500 filas. Dividí el archivo en partes.';end if;
 for r in select * from public.hotel_import_rows where batch_id=p_batch_id and property_id=v_batch.property_id order by row_number loop
  v_norm:=coalesce(r.normalized_data,'{}'::jsonb);v_errors:='[]'::jsonb;v_warnings:='[]'::jsonb;v_action:='import';v_guest:=trim(coalesce(v_norm->>'guest_name',''));v_external:=nullif(trim(coalesce(v_norm->>'external_ref','')),'');v_source_key:=case when v_external is null then null else 'MIG:'||left(lower(regexp_replace(coalesce(v_batch.source_system,'import'),'[^a-zA-Z0-9_-]+','-','g')),40)||':'||left(v_external,160) end;v_room_id:=null;v_room_capacity:=null;v_checkin:=null;v_checkout:=null;v_pax:=1;v_total:=0;v_paid:=0;v_currency:=upper(coalesce(nullif(trim(v_norm->>'currency'),''),'ARS'));v_duplicate_id:=null;
  if v_guest='' then v_errors:=v_errors||jsonb_build_array('Falta el nombre del huésped.');end if;
  begin v_room_id:=nullif(v_norm->>'room_id','')::bigint;exception when others then v_room_id:=null;end;
  if v_room_id is null then v_errors:=v_errors||jsonb_build_array('Falta mapear la habitación.');else select capacidad into v_room_capacity from public.habitaciones where id=v_room_id and property_id=v_batch.property_id and coalesce(activa,true)=true;if not found then v_errors:=v_errors||jsonb_build_array('La habitación mapeada no pertenece al hotel o está inactiva.');end if;end if;
  begin if coalesce(v_norm->>'check_in','')~'^\d{4}-\d{2}-\d{2}$' then v_checkin:=(v_norm->>'check_in')::date;end if;exception when others then v_checkin:=null;end;
  begin if coalesce(v_norm->>'check_out','')~'^\d{4}-\d{2}-\d{2}$' then v_checkout:=(v_norm->>'check_out')::date;end if;exception when others then v_checkout:=null;end;
  if v_checkin is null then v_errors:=v_errors||jsonb_build_array('Fecha de entrada inválida. Usá AAAA-MM-DD.');end if;if v_checkout is null then v_errors:=v_errors||jsonb_build_array('Fecha de salida inválida. Usá AAAA-MM-DD.');end if;if v_checkin is not null and v_checkout is not null and v_checkout<=v_checkin then v_errors:=v_errors||jsonb_build_array('La salida debe ser posterior a la entrada.');end if;
  begin v_pax:=greatest(1,coalesce(nullif(v_norm->>'pax','')::integer,1));exception when others then v_pax:=1;v_errors:=v_errors||jsonb_build_array('Cantidad de huéspedes inválida.');end;if v_room_capacity is not null and v_pax>v_room_capacity then v_warnings:=v_warnings||jsonb_build_array('La cantidad de huéspedes supera la capacidad configurada de la habitación.');end if;
  begin v_total:=coalesce(nullif(v_norm->>'total','')::numeric,0);exception when others then v_total:=0;v_errors:=v_errors||jsonb_build_array('Total inválido.');end;begin v_paid:=coalesce(nullif(v_norm->>'paid_amount','')::numeric,0);exception when others then v_paid:=0;v_errors:=v_errors||jsonb_build_array('Saldo/pago migrado inválido.');end;if v_total<0 then v_errors:=v_errors||jsonb_build_array('El total no puede ser negativo.');end if;if v_paid<0 then v_errors:=v_errors||jsonb_build_array('El pago migrado no puede ser negativo.');end if;if v_paid>v_total and v_total>0 then v_warnings:=v_warnings||jsonb_build_array('El pago migrado supera el total de la reserva.');end if;if v_currency!~'^[A-Z]{3}$' then v_errors:=v_errors||jsonb_build_array('Moneda inválida. Usá un código ISO de 3 letras.');end if;
  if v_checkin is not null and v_checkout is not null and v_checkout<=current_date then v_action:='skip_past';v_warnings:=v_warnings||jsonb_build_array('Estadía histórica: queda fuera de la importación operativa.');elsif v_checkin is not null and v_checkin<current_date then v_errors:=v_errors||jsonb_build_array('La estadía ya comenzó. Cargala manualmente para conciliar el estado actual.');end if;
  v_hash:=md5(lower(v_guest)||'|'||coalesce(v_checkin::text,'')||'|'||coalesce(v_checkout::text,'')||'|'||coalesce(v_room_id::text,'')||'|'||lower(coalesce(v_external,'')));
  if exists(select 1 from public.hotel_import_rows x where x.batch_id=p_batch_id and x.row_number<r.row_number and x.row_hash=v_hash) then v_action:='duplicate';v_warnings:=v_warnings||jsonb_build_array('Fila duplicada dentro del mismo archivo.');end if;
  if jsonb_array_length(v_errors)=0 and v_action='import' then if v_source_key is not null then select id into v_duplicate_id from public.reservas where property_id=v_batch.property_id and codigo_canal=v_source_key limit 1;end if;if v_duplicate_id is null and v_room_id is not null and v_checkin is not null and v_checkout is not null then select id into v_duplicate_id from public.reservas where property_id=v_batch.property_id and lower(trim(nombre_huesped))=lower(v_guest) and fecha_entrada=v_checkin and fecha_salida=v_checkout and(habitacion_id=v_room_id or v_room_id=any(habitaciones_ids)) and lower(coalesce(estado,''))<>'cancelada' and not coalesce(no_show,false) limit 1;end if;if v_duplicate_id is not null then v_action:='duplicate';v_warnings:=v_warnings||jsonb_build_array('Ya existe una reserva equivalente en Habitación Llena.');end if;end if;
  if jsonb_array_length(v_errors)=0 and v_action='import' and v_room_id is not null and v_checkin is not null and v_checkout is not null then if exists(select 1 from public.reservas q where q.property_id=v_batch.property_id and lower(coalesce(q.estado,''))<>'cancelada' and not coalesce(q.no_show,false) and(q.habitacion_id=v_room_id or v_room_id=any(q.habitaciones_ids)) and daterange(q.fecha_entrada,q.fecha_salida,'[)')&&daterange(v_checkin,v_checkout,'[)')) then v_errors:=v_errors||jsonb_build_array('La habitación ya tiene ocupación en esas fechas.');end if;end if;
  if jsonb_array_length(v_errors)>0 then v_action:='invalid';end if;
  update public.hotel_import_rows set row_hash=v_hash,validation=jsonb_build_object('valid',jsonb_array_length(v_errors)=0,'action',v_action,'errors',v_errors,'warnings',v_warnings,'room_id',v_room_id,'source_key',v_source_key,'duplicate_reservation_id',v_duplicate_id),import_status=case v_action when 'invalid' then 'invalid' when 'duplicate' then 'duplicate' when 'skip_past' then 'skipped' else 'valid' end,updated_at=now() where id=r.id;
  if jsonb_array_length(v_warnings)>0 then c_warning:=c_warning+1;end if;if v_action='invalid' then c_invalid:=c_invalid+1;elsif v_action='duplicate' then c_duplicate:=c_duplicate+1;elsif v_action='skip_past' then c_skipped:=c_skipped+1;else c_valid:=c_valid+1;end if;
 end loop;
 update public.hotel_import_batches set status=case when c_invalid=0 then 'ready' else 'validated' end,stats=jsonb_build_object('total',c_total,'valid',c_valid,'invalid',c_invalid,'duplicates',c_duplicate,'skipped',c_skipped,'warning_rows',c_warning),validated_at=now(),updated_at=now() where id=p_batch_id;
 return jsonb_build_object('batch_id',p_batch_id,'total',c_total,'valid',c_valid,'invalid',c_invalid,'duplicates',c_duplicate,'skipped',c_skipped,'warning_rows',c_warning,'ready',c_invalid=0);
end;$function$;

create or replace function public.hl_import_commit_batch(p_batch_id uuid)
returns jsonb language plpgsql security definer set search_path to 'public','private','pg_temp'
as $function$
declare
 v_batch public.hotel_import_batches%rowtype;r public.hotel_import_rows%rowtype;v_norm jsonb;v_room_id bigint;v_lodging_id bigint;v_checkin date;v_checkout date;v_nights integer;v_total numeric;v_paid numeric;v_rate numeric;v_currency text;v_partner_id uuid;v_partner_name text;v_partner_kind text;v_source_key text;v_payments jsonb;v_res public.reservas%rowtype;v_imported integer:=0;v_duplicates integer:=0;v_paid_rows integer:=0;v_skipped integer:=0;
begin
 select * into v_batch from public.hotel_import_batches where id=p_batch_id for update;if not found then raise exception using errcode='P0002',message='Lote de importación no encontrado.';end if;if not private.user_has_property_role(v_batch.property_id,array['owner','manager','admin']) then raise exception using errcode='42501',message='No tenés permisos para ejecutar esta importación.';end if;if v_batch.status not in('ready','validated') or v_batch.validated_at is null then raise exception using errcode='55000',message='Validá el lote antes de importarlo.';end if;if coalesce((v_batch.stats->>'invalid')::integer,0)>0 then raise exception using errcode='22023',message='La importación tiene filas inválidas. Corregilas antes de continuar.';end if;if v_batch.imported_at is not null or v_batch.status='completed' then raise exception using errcode='55000',message='Este lote ya fue importado.';end if;
 perform set_config('app.hl_import_mode','on',true);update public.hotel_import_batches set status='importing',updated_at=now() where id=p_batch_id;
 for r in select * from public.hotel_import_rows where batch_id=p_batch_id and property_id=v_batch.property_id order by row_number loop
  if r.import_status in('duplicate','skipped') then if r.import_status='duplicate' then v_duplicates:=v_duplicates+1;else v_skipped:=v_skipped+1;end if;continue;end if;if r.import_status<>'valid' then raise exception using errcode='22023',message='El lote cambió después de validarse. Volvé a validarlo.';end if;
  v_norm:=r.normalized_data;v_room_id:=(r.validation->>'room_id')::bigint;v_source_key:=nullif(r.validation->>'source_key','');if v_source_key is not null and exists(select 1 from public.reservas where property_id=v_batch.property_id and codigo_canal=v_source_key) then update public.hotel_import_rows set import_status='duplicate',validation=validation||jsonb_build_object('action','duplicate'),updated_at=now() where id=r.id;v_duplicates:=v_duplicates+1;continue;end if;
  select alojamiento_id into v_lodging_id from public.habitaciones where id=v_room_id and property_id=v_batch.property_id and coalesce(activa,true)=true;if not found then raise exception using errcode='23503',message='Una habitación dejó de estar disponible desde la validación.';end if;
  v_checkin:=(v_norm->>'check_in')::date;v_checkout:=(v_norm->>'check_out')::date;v_nights:=greatest(1,v_checkout-v_checkin);v_total:=coalesce(nullif(v_norm->>'total','')::numeric,0);v_paid:=coalesce(nullif(v_norm->>'paid_amount','')::numeric,0);v_currency:=upper(coalesce(nullif(v_norm->>'currency',''),'ARS'));v_rate:=coalesce(nullif(v_norm->>'nightly_rate','')::numeric,case when v_nights>0 then v_total/v_nights else v_total end);
  v_partner_id:=null;v_partner_name:=nullif(trim(coalesce(v_norm->>'partner_name','')),'');v_partner_kind:=case when lower(v_norm->>'partner_kind')='agency' then 'agency' else 'company' end;if v_partner_name is not null then perform pg_advisory_xact_lock(hashtextextended(v_batch.property_id::text||':partner:'||lower(v_partner_name),0));select id into v_partner_id from public.hotel_partners where property_id=v_batch.property_id and kind=v_partner_kind and lower(trim(name))=lower(v_partner_name) order by created_at limit 1;if v_partner_id is null then insert into public.hotel_partners(property_id,kind,name,contact_name,email,phone,notes) values(v_batch.property_id,v_partner_kind,v_partner_name,nullif(v_norm->>'partner_contact',''),nullif(v_norm->>'partner_email',''),nullif(v_norm->>'partner_phone',''),'Creado por Import Center') returning id into v_partner_id;end if;end if;
  v_payments:=case when v_paid>0 then jsonb_build_array(jsonb_build_object('monto',v_paid,'metodo',coalesce(nullif(v_norm->>'payment_method',''),'Migrado'),'moneda',v_currency,'user_id',auth.uid(),'nota','Saldo/pago importado desde '||coalesce(v_batch.source_system,'PMS anterior'))) else '[]'::jsonb end;
  v_res:=public.hl_create_reservation_atomic(jsonb_build_object('property_id',v_batch.property_id,'user_id',auth.uid(),'alojamiento_id',v_lodging_id,'habitacion_id',v_room_id,'habitaciones_ids',jsonb_build_array(v_room_id),'fecha_entrada',v_checkin,'fecha_salida',v_checkout,'tipo_estadia','overnight','nombre_huesped',trim(v_norm->>'guest_name'),'email_huesped',nullif(v_norm->>'email',''),'telefono_huesped',nullif(v_norm->>'phone',''),'dni_huesped',nullif(v_norm->>'document_number',''),'direccion_huesped',nullif(v_norm->>'address',''),'provincia_estado_huesped',nullif(v_norm->>'province',''),'pais_huesped',nullif(v_norm->>'country',''),'cantidad_huespedes',greatest(1,coalesce(nullif(v_norm->>'pax','')::integer,1)),'canal_reserva',coalesce(nullif(v_norm->>'channel',''),'Migración'),'codigo_canal',v_source_key,'tarifa_noche',v_rate,'noches',v_nights,'precio_total',v_total,'moneda',v_currency,'notas',concat_ws(E'\n',nullif(v_norm->>'notes',''),'Migrado desde '||coalesce(v_batch.source_system,'PMS anterior')),'partner_id',v_partner_id,'medio_pago_preferido',nullif(v_norm->>'payment_method',''),'estado',case when lower(v_norm->>'status')='pendiente' then 'pendiente' else 'confirmada' end,'no_show',false),v_payments);
  update public.reservas set tipo_documento_huesped=nullif(v_norm->>'document_type',''),fecha_nacimiento_huesped=case when coalesce(v_norm->>'birth_date','')~'^\d{4}-\d{2}-\d{2}$' then(v_norm->>'birth_date')::date else null end,nacionalidad_huesped=nullif(v_norm->>'nationality',''),ciudad_huesped=nullif(v_norm->>'city',''),idioma_huesped=nullif(v_norm->>'language','') where id=v_res.id and property_id=v_batch.property_id;
  update public.hotel_import_rows set import_status='imported',imported_reservation_id=v_res.id,updated_at=now() where id=r.id;v_imported:=v_imported+1;if v_paid>0 then v_paid_rows:=v_paid_rows+1;end if;
 end loop;
 update public.hotel_import_batches set status='completed',imported_at=now(),imported_by=auth.uid(),updated_at=now(),stats=coalesce(stats,'{}'::jsonb)||jsonb_build_object('imported',v_imported,'duplicates',v_duplicates,'skipped',v_skipped,'payments_imported',v_paid_rows) where id=p_batch_id;
 update public.hotel_onboarding_projects set checklist=jsonb_set(coalesce(checklist,'{}'::jsonb),'{data}',coalesce(checklist->'data','{}'::jsonb)||jsonb_build_object('mapping',true,'future_reservations',true,'guests',v_imported>0,'balances',v_paid_rows>0),true),status=case when status='live' then status else 'importing' end,updated_by=auth.uid(),updated_at=now() where property_id=v_batch.property_id;
 return jsonb_build_object('batch_id',p_batch_id,'imported',v_imported,'duplicates',v_duplicates,'skipped',v_skipped,'payments_imported',v_paid_rows,'completed',true);
exception when others then update public.hotel_import_batches set status='failed',updated_at=now() where id=p_batch_id;raise;end;$function$;

revoke all on function public.hl_import_validate_batch(uuid) from public,anon,authenticated;
revoke all on function public.hl_import_commit_batch(uuid) from public,anon,authenticated;
grant execute on function public.hl_import_validate_batch(uuid) to authenticated;
grant execute on function public.hl_import_commit_batch(uuid) to authenticated;
